+    @for (int i = 0; i < _stepNames.Length; i++)
+    {
+        var stepIndex = i;
+        var stepClass = GetStepClass(stepIndex);
+        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
+            <div class="step-circle">
+                @if (stepIndex < _currentStep)
+                {
+                    <span>&#10003;</span>
+                }
+                else
+                {
+                    <span>@(stepIndex + 1)</span>
+                }
+            </div>
+            <div class="step-label">@_stepNames[stepIndex]</div>
+        </div>
+        @if (i < _stepNames.Length - 1)
+        {
+            <div class="step-connector"></div>
+        }
+    }
+</div>
+
+@if (!string.IsNullOrEmpty(_errorMessage))
+{
+    <div class="alert alert-danger mt-3">@_errorMessage</div>
+}
+
+@* Step 1: Personal Info *@
+@if (_currentStep == 0)
+{
+    <div class="form-section">
+        <h3>Personal Information</h3>
+        <div class="mb-3">
+            <label class="form-label">Full Name *</label>
+            <input type="text" class="form-control" @bind="_fullName" />
+        </div>
+        <div class="mb-3">
+            <label class="form-label">Email *</label>
+            <input type="email" class="form-control" @bind="_email" />
+        </div>
+        <div class="mb-3">
+            <label class="form-label">Phone *</label>
+            <input type="tel" class="form-control" @bind="_phone" />
+        </div>
+        <div class="mb-3">
+            <label class="form-label">Address *</label>
+            <input type="text" class="form-control" @bind="_address" />
+        </div>
+        <div class="d-flex justify-content-end">
+            <button class="btn btn-primary" @onclick="NextFromPersonalInfo">Next</button>
+        </div>
+    </div>
+}
+
+@* Step 2: Work History *@
+@if (_currentStep == 1)
+{
+    <div class="form-section">
+        <h3>Work History</h3>
+        @for (int i = 0; i < _workEntries.Count; i++)
+        {
+            var index = i;
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center mb-2">
+                    <h5>Position @(index + 1)</h5>
+                    @if (_workEntries.Count > 1)
+                    {
+                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                    }
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Company Name *</label>
+                    <input type="text" class="form-control" @bind="_workEntries[index].Company" />
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Job Title *</label>
+                    <input type="text" class="form-control" @bind="_workEntries[index].Title" />
+                </div>
+                <div class="row mb-2">
+                    <div class="col-md-6">
+                        <label class="form-label">Start Date *</label>
+                        <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
+                    </div>
+                    <div class="col-md-6">
+                        <label class="form-label">End Date</label>
+                        <input type="date" class="form-control" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
+                        <div class="form-check mt-1">
+                            <input type="checkbox" class="form-check-input" id="current-@index" @bind="_workEntries[index].IsCurrent" />
+                            <label class="form-check-label" for="current-@index">Currently working here</label>
+                        </div>
+                    </div>
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Description</label>
+                    <textarea class="form-control" rows="3" @bind="_workEntries[index].Description"></textarea>
+                </div>
+            </div>
+        }
+        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">Add Another Position</button>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+        </div>
+    </div>
+}
+
+@* Step 3: References *@
+@if (_currentStep == 2)
+{
+    <div class="form-section">
+        <h3>References</h3>
+        @for (int i = 0; i < _references.Count; i++)
+        {
+            var index = i;
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center mb-2">
+                    <h5>Reference @(index + 1)</h5>
+                    @if (_references.Count > 2)
+                    {
+                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(index)">Remove</button>
+                    }
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Name *</label>
+                    <input type="text" class="form-control" @bind="_references[index].Name" />
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Relationship *</label>
+                    <input type="text" class="form-control" @bind="_references[index].Relationship" />
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Email *</label>
+                    <input type="email" class="form-control" @bind="_references[index].Email" />
+                </div>
+                <div class="mb-2">
+                    <label class="form-label">Phone *</label>
+                    <input type="tel" class="form-control" @bind="_references[index].Phone" />
+                </div>
+            </div>
+        }
+        @if (_references.Count < 3)
+        {
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">Add Reference</button>
+        }
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+        </div>
+    </div>
+}
+
+@* Step 4: Cover Letter *@
+@if (_currentStep == 3)
+{
+    <div class="form-section">
+        <h3>Cover Letter</h3>
+        <div class="mb-3">
+            <textarea class="form-control" rows="12" maxlength="2000" @bind="_coverLetter" @bind:event="oninput"></textarea>
+            <div class="text-muted mt-1">@_coverLetter.Length / 2000 characters</div>
+        </div>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep">Next</button>
+        </div>
+    </div>
+}
+
+@* Step 5: Review & Submit *@
+@if (_currentStep == 4)
+{
+    @if (_submitted)
+    {
+        <div class="form-section text-center">
+            <h3 class="text-success">Application Submitted!</h3>
+            <p class="fs-5">Your application has been received.</p>
+            <p class="fs-4 fw-bold">Application ID: @_applicationId</p>
+        </div>
+    }
+    else
+    {
+        <div class="form-section">
+            <h3>Review & Submit</h3>
+
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Personal Information</h5>
+                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(0)'>Edit</a>
+                </div>
+                <p><strong>Name:</strong> @_fullName</p>
+                <p><strong>Email:</strong> @_email</p>
+                <p><strong>Phone:</strong> @_phone</p>
+                <p><strong>Address:</strong> @_address</p>
+            </div>
+
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Work History</h5>
+                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(1)'>Edit</a>
+                </div>
+                @foreach (var entry in _workEntries)
+                {
+                    <div class="mb-2 border-bottom pb-2">
+                        <p><strong>@entry.Title</strong> at @entry.Company</p>
+                        <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p>@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>References</h5>
+                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(2)'>Edit</a>
+                </div>
+                @foreach (var reference in _references)
+                {
+                    <div class="mb-2 border-bottom pb-2">
+                        <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
+                        <p>@reference.Email | @reference.Phone</p>
+                    </div>
+                }
+            </div>
+
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Cover Letter</h5>
+                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(3)'>Edit</a>
+                </div>
+                <p style="white-space: pre-wrap;">@_coverLetter</p>
+            </div>
+
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                    @if (_isSubmitting)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1"></span>
+                    }
+                    Submit Application
+                </button>
+            </div>
+        </div>
+    }
+}
+
+@code {
+    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private int _currentStep = 0;
+    private string _errorMessage = string.Empty;
+
+    // Step 1: Personal Info
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+
+    // Step 2: Work History
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string _coverLetter = string.Empty;
+
+    // Step 5: Submission
+    private bool _isSubmitting = false;
+    private bool _submitted = false;
+    private int _applicationId;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == _currentStep) return "active";
+        if (stepIndex < _currentStep) return "completed";
+        return "future";
+    }
+
+    private void NavigateToStep(int step)
+    {
+        if (step < _currentStep)
+        {
+            _currentStep = step;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private async Task NextFromPersonalInfo()
+    {
+        _errorMessage = string.Empty;
+
+        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
+            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+        {
+            _errorMessage = "All fields are required.";
+            return;
+        }
+
+        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+        if (!emailValid)
+        {
+            _errorMessage = "Please enter a valid email address.";
+            return;
+        }
+
+        NextStep();
+    }
+
+    private void NextFromWorkHistory()
+    {
+        _errorMessage = string.Empty;
+
+        foreach (var entry in _workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
+                || entry.StartDate == default)
+            {
+                _errorMessage = "Company, job title, and start date are required for all positions.";
+                return;
+            }
+        }
+
+        NextStep();
+    }
+
+    private void NextFromReferences()
+    {
+        _errorMessage = string.Empty;
+
+        foreach (var r in _references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
+                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                _errorMessage = "All fields are required for each reference.";
+                return;
+            }
+        }
+
+        NextStep();
+    }
+
+    private void NextStep()
+    {
+        _errorMessage = string.Empty;
+        if (_currentStep < _stepNames.Length - 1)
+            _currentStep++;
+    }
+
+    private void PreviousStep()
+    {
+        _errorMessage = string.Empty;
+        if (_currentStep > 0)
+            _currentStep--;
+    }
+
+    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (_workEntries.Count > 1)
+            _workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3)
+            _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (_references.Count > 2)
+            _references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _errorMessage = string.Empty;
+
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workHistory = new WorkHistory(_workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? string.Empty)
+            ).ToList());
+            var references = _references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
+            ).ToList();
+
+            var application = new JobApplication(personal, workHistory, references, _coverLetter);
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string? Description { get; set; }
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+

toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 1.5rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step.future {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background-color: #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    color: #495057;
}

.step.active .step-circle {
    background-color: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    background-color: #198754;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.25rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    flex: 1;
    height: 2px;
    background-color: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    align-self: center;
    margin-bottom: 1rem;
}

.form-section {
    max-width: 700px;
    margin: 1rem auto;
}

